=== Method: aBrkThrMax (AbstractMethod) ===
return aBrkThrMax;


=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to determine the necessary brake request,
   which is required to maintain the vehicle in standstill */

// Determine based on slope a meaningful target brake request
if(CSM_ASlopeQualifier != CSMASlopeQuality_notReliable)
{
	aBrkThrMax = -CSM_Slope.abs() * (CSMMassVehicleEmpty + C_CSM_MassAddOn) / CSMMassVehicleEmpty;
	aBrkThrMax =  aBrkThrMax - (C_CSM_ABrkOffset.getAt(CSM_Slope)) - C_CSM_ABrkOffsetAActPropConst;
	if(CsmDisableLeakageComp == false)
	{
		aBrkThrMax = aBrkThrMax - (CsmALeakageComp.abs());
	}else
	{
		aBrkThrMax = aBrkThrMax;
	}		//Enable additional brake request limitation (e.g. to 45bar)	if(FS_CSM_HoldLimitInitBrakeRequest)	{		aBrkThrMax = aBrkThrMax.max(CSMATarBrkWithNoSlope);
	}else	{		aBrkThrMax = aBrkThrMax;
	}	
// in case slope estimation isn't possible then default value should be considered
}else
{
	aBrkThrMax = CSMATarBrkWithNoSlope;
}


aBrkThrMax = aBrkThrMax.min(C_CSM_ABrkThrMaxMinimum);
